using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;using Newtonsoft.Json.Linq;
public static class VAApply {
 static string R=>Path.GetFullPath(Path.Combine(Application.dataPath,"../../.."));
 static Vector3 V(JToken t)=>new Vector3((float)t[0],(float)t[1],(float)t[2]);
 public static object Run(string mode){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B2_Circular.unity"))throw new Exception("Clean saved B2 required");var h=R+"/SourceAssets/VarcoPropAlignment";var data=JObject.Parse(File.ReadAllText(h+"/before.json"));var models=JArray.Parse(File.ReadAllText(h+"/repair_models.json"));var assets=new Dictionary<string,Mesh[]>();
 foreach(var m in models){string p=(string)m["asset"];AssetDatabase.ImportAsset(p,ImportAssetOptions.ForceSynchronousImport);var imp=(ModelImporter)AssetImporter.GetAtPath(p);imp.materialImportMode=ModelImporterMaterialImportMode.None;imp.isReadable=false;imp.importNormals=ModelImporterNormals.Import;imp.importTangents=ModelImporterTangents.CalculateMikk;imp.importAnimation=false;imp.SaveAndReimport();assets[(string)m["model"]]=AssetDatabase.LoadAllAssetsAtPath(p).OfType<Mesh>().OrderBy(x=>x.name).ToArray();}
 var all=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var report=new List<object>();
 foreach(var row in data["rows"].Where(x=>assets.ContainsKey((string)x["model"]))){var root=all.Single(x=>x.name==(string)row["name"]);if(root.Find("Aligned_LOD0"))throw new Exception("Already applied");if(Vector3.Distance(root.position,V(row["position"]))>.0001f)throw new Exception("Placement changed: "+root.name);
 var oldRows=row["renderers"].ToArray();var oldRs=oldRows.Select(x=>{GlobalObjectId.TryParse((string)x["id"],out var id);return (MeshRenderer)GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id);}).ToArray();if(oldRs.Any(x=>!x||!x.enabled))throw new Exception("Renderer state changed");var meshes=assets[(string)row["model"]];if(meshes.Length!=oldRs.Length)throw new Exception("LOD count mismatch");
 var src=oldRs[0];var oldMesh=src.GetComponent<MeshFilter>().sharedMesh;var pts=oldMesh.vertices.Select(v=>root.InverseTransformPoint(src.transform.TransformPoint(v))).ToArray();var oldBounds=new Bounds(pts[0],Vector3.zero);foreach(var v in pts)oldBounds.Encapsulate(v);var nb=meshes[0].bounds;var scale=new Vector3(oldBounds.size.x/nb.size.x,oldBounds.size.y/nb.size.y,oldBounds.size.z/nb.size.z);if(Mathf.Max(Mathf.Abs(scale.x-1),Mathf.Abs(scale.y-1),Mathf.Abs(scale.z-1))>.03f)throw new Exception("Unexpected source dimensions: "+root.name+" "+scale);var offset=oldBounds.center-Vector3.Scale(nb.center,scale);
 var map=new Dictionary<Renderer,Renderer>();for(int i=0;i<oldRs.Length;i++){var old=oldRs[i];var g=new GameObject("Aligned_LOD"+i);g.transform.SetParent(root,false);g.transform.localPosition=offset;g.transform.localRotation=Quaternion.identity;g.transform.localScale=scale;g.layer=old.gameObject.layer;GameObjectUtility.SetStaticEditorFlags(g,GameObjectUtility.GetStaticEditorFlags(old.gameObject));g.AddComponent<MeshFilter>().sharedMesh=meshes[i];var nr=g.AddComponent<MeshRenderer>();EditorUtility.CopySerialized(old,nr);nr.enabled=true;old.enabled=false;PrefabUtility.RecordPrefabInstancePropertyModifications(old);map[old]=nr;}
 foreach(var lod in root.GetComponentsInChildren<LODGroup>(true)){var levels=lod.GetLODs();for(int i=0;i<levels.Length;i++)levels[i].renderers=levels[i].renderers.Select(r=>map.TryGetValue(r,out var n)?n:r).ToArray();lod.SetLODs(levels);PrefabUtility.RecordPrefabInstancePropertyModifications(lod);}
 foreach(var c in row["colliders"]){GlobalObjectId.TryParse((string)c["id"],out var id);var obj=GlobalObjectId.GlobalObjectIdentifierToObjectSlow(id);if(EditorJsonUtility.ToJson(obj)!=(string)c["json"])throw new Exception("Collider changed");}
 report.Add(new{name=root.name,model=(string)row["model"],lods=meshes.Length,scale=new[]{scale.x,scale.y,scale.z},offset=new[]{offset.x,offset.y,offset.z},originalCollidersPreserved=true});
 }
 EditorSceneManager.MarkSceneDirty(s);if(mode=="save")EditorSceneManager.SaveScene(s);File.WriteAllText(h+"/applied_"+mode+".json",JsonConvert.SerializeObject(report,Formatting.Indented));return new{mode,placements=report.Count,saved=mode=="save"};
 }
}
